const underworldLanternSheet=new Image();underworldLanternSheet.assetSrc='assets/underworld-lantern-v2.png';
function beginUnderworldLantern(e){let origin={x:e.x,y:e.y},center={x:p.x,y:p.y};e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'underworldSoulLights',bespoke:true,windup:3.2,origin,previous:{...center},fired:false,lights:[0,1,2].map(i=>{let angle=i*Math.PI*2/3,point={x:center.x+Math.cos(angle)*90,y:center.y+Math.sin(angle)*90};return {...point,valid:passable(point.x,point.y,12)&&lineClear(origin,point),extinguished:false};})};}
function underworldLanternContact(point,from,to){let dx=to.x-from.x,dy=to.y-from.y,len=dx*dx+dy*dy,t=len?Math.max(0,Math.min(1,((point.x-from.x)*dx+(point.y-from.y)*dy)/len)):0;return Math.hypot(point.x-from.x-dx*t,point.y-from.y-dy*t)<=28+1e-8;}
const underworldLanternAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e1')return underworldLanternAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='underworldSoulLights'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=350&&clear){beginUnderworldLantern(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,60*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=.6&&before<=3.2&&dist(a.previous,p)<=220&&lineClear(a.previous,p,13)){let span=e.elapsed-before||1,lerp=t=>({x:a.previous.x+(p.x-a.previous.x)*t,y:a.previous.y+(p.y-a.previous.y)*t}),from=lerp(Math.max(0,(.6-before)/span)),to=lerp(Math.min(1,(3.2-before)/span));for(let light of a.lights)if(light.valid&&!light.extinguished&&underworldLanternContact(light,from,to)&&lineClear(light,p)){light.extinguished=true;light.extinguishedAt=e.elapsed;p.sp=Math.min(maxsp(),(p.sp||0)+8);playSound('impact',light.x,light.y);}}
 a.previous={x:p.x,y:p.y};if(!a.fired&&e.elapsed>=3.2){a.fired=true;e.struck=true;if(a.lights.some(light=>light.valid&&!light.extinguished&&dist(light,p)<=110&&lineClear(a.origin,light)&&lineClear(light,p)))hurt(72);playSound('impact',e.x,e.y);}
 if(e.elapsed>=4.2){e.attack=null;e.state='idle';e.t=3.4;}
};
const underworldLanternDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e1'||!underworldLanternSheet.complete||!underworldLanternSheet.naturalWidth||!underworldLanternSheet.naturalHeight)return underworldLanternDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='underworldSoulLights')f={row:2,col:e.elapsed<.6?0:e.elapsed<3.2?1:e.elapsed<3.45?2:3};let q=project(e.x,e.y),sw=underworldLanternSheet.naturalWidth/4,sh=underworldLanternSheet.naturalHeight/3,w=210,h=w*sh/sw,anchor=[[.91,.9,.9,.91],[.87,.86,.81,.81],[.83,.83,.84,.84]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-14-Math.sin((e.anim||0)*2)*3);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,underworldLanternSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(underworldLanternSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const underworldLanternSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e1'?165:underworldLanternSizeBase(e);
const underworldLanternGroundBase=drawGroundEffects;drawGroundEffects=()=>{underworldLanternGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e1'):enemies)){let a=e.attack;if(e.species!=='r10e1'||e.hp<=0||a?.pattern!=='underworldSoulLights')continue;for(let light of a.lights){if(!light.valid||!visibleAt(light.x,light.y))continue;if(light.extinguished){if(e.elapsed-light.extinguishedAt<.35)groundRing(light.x,light.y,35,'#92f0c2',3);continue;}if(e.elapsed>3.45)continue;let color=a.fired?'#f4ddff':e.elapsed<.6?'#8b799d':'#d1b1ef';groundRing(light.x,light.y,110,color,1);groundRing(light.x,light.y,28,'#97ebce',3);let q=project(light.x,light.y);ctx.save();ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(q.x,q.y-12,6,10,0,0,Math.PI*2);ctx.fill();ctx.restore();}}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e1',animateEnemy,drawRegionEnemy);
